locked.scoped_css:
@scope (.slide[data-layout-id="paper-ink.relationship.C4"]) {
svg.scene { position: absolute; inset: 0; z-index: 1; }
  /* ECharts 地图画布：铺在主图区，让 registerMap 渲染真实省/市界 */
  #chart {
    position: absolute;
    left: 120px; top: 131px;
    width: 1095px; height: 750px;
    z-index: 2;
  }
  /* SVG 节点叠层：盖在 echarts canvas 之上，画双圈节点/数值/城市名 */
  svg.overlay {
    position: absolute; left: 0; top: 0;
    width: 1920px; height: 1080px;
    z-index: 3; pointer-events: none;
  }
  .caption {
    position: absolute; left: 0; right: 0; bottom: 118px;
    text-align: center;
    font-family: var(--sans); font-weight: 400;
    font-size: var(--type-caption); letter-spacing: .04em;
    color: var(--ink);
    z-index: 5;
  }
}
